from __future__ import annotations

import json
import shutil
from pathlib import Path


ROOT = Path(__file__).resolve().parents[1]
WEB = ROOT / "web"
PUBLIC_DATA = WEB / "public" / "data"
DIST = WEB / "dist"


CSS = """
:root{font-family:Inter,Segoe UI,system-ui,sans-serif;color:#172033;background:#f4f7fb}*{box-sizing:border-box}body{margin:0}button,input,select{font:inherit}.shell{width:min(1440px,calc(100% - 32px));margin:auto;padding:18px 0 40px}.hero{min-height:360px;display:grid;grid-template-columns:minmax(0,1.1fr)360px;gap:28px;align-items:center;padding:34px;border:1px solid #d8e1ea;border-radius:8px;background:linear-gradient(135deg,#fff,#ebf4ff)}.eyebrow{color:#2563eb;font-weight:800;text-transform:uppercase;font-size:.78rem;margin:0 0 8px}h1{font-size:clamp(3rem,7vw,6.5rem);line-height:.92;margin:0 0 18px}h2{font-size:2rem;margin:0 0 10px}p{color:#475569;line-height:1.55}.metrics{display:grid;grid-template-columns:repeat(4,minmax(110px,1fr));gap:10px;margin-top:28px}.metrics span,.panel,.rail,.card,.note{border:1px solid #d8e1ea;background:#fff;border-radius:8px}.metrics span{padding:12px;color:#64748b}.metrics strong{display:block;font-size:1.6rem;color:#172033}.orbit{position:relative;width:310px;aspect-ratio:1;border:1px solid #c8d7e8;border-radius:50%;display:grid;place-items:center;justify-self:center;background:#fff;box-shadow:inset 0 0 0 28px #f2f7fc,0 24px 60px #2563eb29}.orbit:before,.orbit:after{content:"";position:absolute;border-radius:50%;border:1px solid #c8d7e8}.orbit:before{inset:56px}.orbit:after{inset:96px}.orbit b{font-size:4.5rem;z-index:2}.nav{position:sticky;top:0;z-index:3;display:flex;gap:8px;flex-wrap:wrap;padding:12px 0;background:#f4f7fbee;backdrop-filter:blur(10px)}.nav button,.pill,.cmd{border:1px solid #c8d7e8;background:#fff;color:#172033;border-radius:8px;padding:10px 14px;cursor:pointer}.nav button.active,.pill.active,.cmd{background:#17345f;color:#fff}.panel{padding:22px;min-height:620px}.grid{display:grid;grid-template-columns:280px minmax(0,1fr);gap:18px}.rail{padding:16px;position:sticky;top:76px}.pill{width:100%;text-align:left;margin:5px 0}.cards{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px}.card,.note{padding:14px}.mini{height:130px;width:100%}.sim{display:grid;grid-template-columns:minmax(0,1.2fr)360px;gap:16px}.plot{width:100%;min-height:320px}.slider{display:grid;grid-template-columns:1fr minmax(120px,1fr)58px;gap:10px;align-items:center;margin:12px 0;color:#475569}input[type=range]{width:100%;accent-color:#2563eb}.graphCanvas{width:100%;height:540px;border:1px solid #c8d7e8;border-radius:8px;background:#f8fbff}.detail{margin-top:12px}.targetList{max-height:620px;overflow:auto;display:grid;gap:6px}.target{text-align:left;border:1px solid #d8e1ea;background:#fff;border-radius:8px;padding:9px;cursor:pointer}.target.active{border-color:#2563eb;background:#eff6ff}.trace{display:grid;grid-template-columns:repeat(5,minmax(120px,1fr));gap:10px}.trace div{border:1px solid #d8e1ea;border-radius:8px;padding:12px;background:#f8fbff}.risk{height:32px;border-radius:999px;background:linear-gradient(90deg,#0f766e,#ca8a04,#dc2626);margin:18px 0}.search{width:100%;border:1px solid #c8d7e8;border-radius:8px;padding:10px;margin:6px 0}.notes{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:12px;margin-top:16px}textarea{width:100%;min-height:260px;border:1px solid #d8e1ea;border-radius:8px;padding:12px;background:#f8fbff}@media(max-width:980px){.hero,.grid,.sim{grid-template-columns:1fr}.cards,.metrics,.notes,.trace{grid-template-columns:1fr 1fr}.rail{position:static}}@media(max-width:620px){.shell{width:calc(100% - 18px)}h1{font-size:3rem}.hero{padding:20px}.cards,.metrics,.notes,.trace{grid-template-columns:1fr}}
"""


JS = r"""
let atlas;let view='journey';let selectedSim='transition_pressure_lab';let selectedTarget='OC14-N001';let graphQuery='';
const $=s=>document.querySelector(s);const root=$('#app');
function hash(x){const t=JSON.stringify(x,Object.keys(x).sort());let h=2166136261;for(let i=0;i<t.length;i++){h^=t.charCodeAt(i);h=Math.imul(h,16777619)}return (h>>>0).toString(16).padStart(8,'0')}
function nav(){return ['journey:OC in 12 minutes','concepts:Concept Atlas','simulations:Simulation Lab','graph:Science Graph','proof:Evidence / Boundaries','case:Case Studio','reviewer:Reviewer Mode'].map(x=>{const [id,label]=x.split(':');return `<button class="${view===id?'active':''}" onclick="view='${id}';render()">${label}</button>`}).join('')}
function hero(){return `<header class="hero"><div><p class="eyebrow">OC Core 1.4 scientific exhibit</p><h1>Ontology of Continua</h1><p>A guided, visual and reproducible demonstration of continua, boundaries, operators, coherence, collapse, emergence, projections and proof limits.</p><div class="metrics"><span><strong>${atlas.graph.summary.target_total}</strong> public targets</span><span><strong>${atlas.graph.summary.node_total}</strong> graph nodes</span><span><strong>${atlas.simulations.length}</strong> visual labs</span><span><strong>0</strong> external actions</span></div></div><div class="orbit"><b>OC</b></div></header><nav class="nav">${nav()}</nav>`}
function mini(c){return `<svg class="mini" viewBox="0 0 180 130"><circle cx="90" cy="65" r="52" fill="none" stroke="${c.color}" stroke-width="3"/><circle cx="90" cy="65" r="28" fill="#fff" stroke="#dbe4ee"/><path d="M34 82 C62 38 91 92 146 43" fill="none" stroke="${c.color}" stroke-width="4" stroke-linecap="round"/><circle cx="52" cy="79" r="8" fill="${c.color}"/><circle cx="91" cy="65" r="8" fill="${c.color}"/><circle cx="128" cy="47" r="8" fill="${c.color}"/></svg>`}
function journey(){return `<section class="panel"><p class="eyebrow">${atlas.journeys[0].audience}</p><h2>${atlas.journeys[0].title}</h2><p>${atlas.journeys[0].promise}</p><div class="cards">${atlas.journeys[0].steps.map((s,i)=>`<button class="card" onclick="view='${s.simulation?'simulations':s.view==='science_graph'?'graph':s.view==='proof_evidence'?'proof':'concepts'}';render()"><strong>${i+1}. ${s.title}</strong><p>${s.minutes} min</p></button>`).join('')}</div></section>`}
function concepts(){let selected=atlas.concepts[0];return `<section class="grid"><aside class="rail"><h2>Concept Atlas</h2>${atlas.concepts.map(c=>`<button class="pill" onclick="document.querySelector('[data-concept]').innerHTML=conceptDetail('${c.id}')">${c.title}</button>`).join('')}</aside><main class="panel" data-concept>${conceptDetail(selected.id)}</main></section>`}
function conceptDetail(id){const c=atlas.concepts.find(x=>x.id===id)||atlas.concepts[0];return `<p class="eyebrow">${c.visual_metaphor}</p><h2>${c.title}</h2><p>${c.short}</p>${mini(c)}<div class="notes"><div class="note"><strong>Learning goal</strong><br>${c.learning_goal}</div><div class="note"><strong>Try it</strong><br>${c.try_it}</div><div class="note"><strong>Nonclaim</strong><br>${c.nonclaim}</div></div>`}
function runSim(id,p){if(id==='transition_pressure_lab'){let c=p.initial_coherence??.52,s=[];for(let step=0;step<=(p.steps??30);step++){s.push({step,value:+c.toFixed(6)});let stress=Math.max(0,(p.transition_pressure??.64)-(p.corrective_capacity??.38));c+=.08*(p.corrective_capacity??.38)*(1-c)-.06*stress-.035*(p.coupling_drag??.44)*c;c=Math.max(0,Math.min(1,c))}return {series:s,score:s.at(-1).value,band:s.at(-1).value<.34?'fragile':s.at(-1).value<.67?'recoverable':'stable'}}if(id==='degradation_recovery_lab'){let h=p.initial_health??.74,s=[];for(let step=0;step<=(p.steps??36);step++){s.push({step,value:+h.toFixed(6)});let repair=step>=(p.intervention_step??14)?(p.intervention_strength??.22):0;h+=repair*(1-h)*.18-(p.degradation_rate??.08)*(.6+h);h=Math.max(0,Math.min(1,h))}return {series:s,score:s.at(-1).value,band:s.at(-1).value<.34?'continued degradation':s.at(-1).value<.67?'partial recovery':'recovered'}}let comps={source_binding:p.source_binding??.82,dependency_closure:p.dependency_closure??.76,verification_strength:p.verification_strength??.7,nonclaim_clarity:p.nonclaim_clarity??.68};let score=comps.source_binding*.25+comps.dependency_closure*.25+comps.verification_strength*.3+comps.nonclaim_clarity*.2;return {series:Object.values(comps).map((v,i)=>({step:i,value:v})),score:+score.toFixed(6),band:score<.34?'insufficient':score<.67?'reviewable':'strong'}}
function plot(series){let max=Math.max(1,...series.map(p=>p.value)),pts=series.map(p=>[24+p.step*(392/Math.max(1,series.at(-1).step)),190-p.value*(172/max)]);let d=pts.map((p,i)=>(i?'L':'M')+p[0]+','+p[1]).join(' ');return `<svg class="plot" viewBox="0 0 440 220"><rect width="440" height="220" rx="10" fill="#f8fbff"/><path d="${d}" fill="none" stroke="#2563eb" stroke-width="4" stroke-linecap="round"/></svg>`}
function simulations(){const spec=atlas.simulations.find(s=>s.id===selectedSim)||atlas.simulations[0];const params=Object.fromEntries(Object.entries(spec.parameters).filter(([k,b])=>typeof b.default==='number').map(([k,b])=>[k,b.default]));const r=runSim(spec.id,params);return `<section class="grid"><aside class="rail"><h2>Simulation Lab</h2>${atlas.simulations.map(s=>`<button class="pill ${s.id===spec.id?'active':''}" onclick="selectedSim='${s.id}';render()">${s.title}</button>`).join('')}</aside><main class="panel"><p class="eyebrow">${spec.visual_type}</p><h2>${spec.title}</h2><p>${spec.purpose}</p><div class="sim"><div>${plot(r.series)}<h3>${r.band} ${r.score}</h3></div><div class="card">${Object.entries(spec.parameters).map(([k,b])=>typeof b.default==='number'?`<label class="slider"><span>${k.replaceAll('_',' ')}</span><input type="range" min="${b.min??0}" max="${b.max??1}" step="${b.type==='integer'?1:.01}" value="${b.default}"><b>${b.default}</b></label>`:'').join('')}<p>hash ${hash({id:spec.id,params,r})}</p></div></div><div class="notes"><div class="note"><strong>Boundary</strong><br>${spec.limits[0]}</div><div class="note"><strong>Evidence</strong><br>${spec.evidence_refs.join(', ')}</div></div></main></section>`}
function graphView(){return `<section class="grid"><aside class="rail"><h2>Science Graph</h2><input class="search" placeholder="Search" value="${graphQuery}" onchange="graphQuery=this.value;render()"><p>${atlas.graph.nodes.length} nodes / ${atlas.graph.edges.length} edges</p></aside><main class="panel"><h2>Public Science Graph</h2><canvas class="graphCanvas" width="1000" height="540"></canvas><div class="detail"><strong>Interactive canvas</strong><p>Clustered public graph with demonstrated-by and ordered-neighbor relations. Search narrows rendered nodes.</p></div></main></section>`}
function drawGraph(){const c=document.querySelector('canvas.graphCanvas');if(!c)return;const ctx=c.getContext('2d'),w=c.width,h=c.height;ctx.clearRect(0,0,w,h);const q=graphQuery.toLowerCase();const nodes=atlas.graph.nodes.filter(n=>!q||JSON.stringify(n).toLowerCase().includes(q)).slice(0,220),ids=new Set(nodes.map(n=>n.id)),colors={structural:'#2563eb','proof-only':'#7c3aed',simulations:'#0f766e','proof-browser':'#dc2626'};function xy(n){return [w/2+n.x*42,h/2+n.y*42]}ctx.globalAlpha=.35;atlas.graph.edges.forEach(e=>{if(ids.has(e.source)&&ids.has(e.target)){let a=nodes.find(n=>n.id===e.source),b=nodes.find(n=>n.id===e.target),A=xy(a),B=xy(b);ctx.strokeStyle=e.relation==='demonstrated-by'?'#94a3b8':'#cbd5e1';ctx.beginPath();ctx.moveTo(A[0],A[1]);ctx.lineTo(B[0],B[1]);ctx.stroke()}});ctx.globalAlpha=1;nodes.forEach(n=>{let [x,y]=xy(n);ctx.fillStyle=colors[n.cluster]||'#64748b';ctx.beginPath();ctx.arc(x,y,n.size,0,Math.PI*2);ctx.fill()})}
function proof(){let matches=atlas.proof_routes.filter(r=>!graphQuery||JSON.stringify(r).toLowerCase().includes(graphQuery.toLowerCase()));let route=atlas.proof_routes.find(r=>r.target_id===selectedTarget)||matches[0]||atlas.proof_routes[0];return `<section class="grid"><aside class="rail"><h2>Evidence / Boundaries</h2><input class="search" placeholder="Search" value="${graphQuery}" onchange="graphQuery=this.value;render()"><div class="targetList">${matches.slice(0,80).map(r=>`<button class="target ${r.target_id===route.target_id?'active':''}" onclick="selectedTarget='${r.target_id}';render()"><strong>${r.target_id}</strong><span>${r.demo_class}</span></button>`).join('')}</div></aside><main class="panel"><p class="eyebrow">${route.status}</p><h2>${route.label}</h2><p>${route.statement_excerpt}</p><div class="trace">${route.trace.map((t,i)=>`<div><strong>${i+1}</strong><br>${t}</div>`).join('')}</div><div class="notes"><div class="note"><strong>Rationale</strong><br>${route.rationale}</div><div class="note"><strong>Boundary reason</strong><br>${route.non_simulated_reason}</div><div class="note"><strong>What this does not prove</strong><br>No external peer review, no private trace exposure, no proof-engine claim.</div></div></main></section>`}
function caseStudio(){return `<section class="panel"><p class="eyebrow">bounded diagnostic workflow</p><h2>Case Studio</h2><p>Translate a transformation or AI governance case into visible OC diagnostic factors.</p><div class="risk"></div><h3>Risk reading: attention</h3><div class="notes"><div class="note">Boundary clarity, evidence quality and dependency coupling are the first practical levers.</div><div class="note">This is not a client-specific guarantee.</div></div></section>`}
function reviewer(){const b={title:atlas.title,schema_version:atlas.schema_version,counts:atlas.generated_from,nonclaim:'Local public exhibit only.'};return `<section class="panel"><p class="eyebrow">reviewer trust surface</p><h2>Reviewer Mode</h2>${atlas.reviewer_mode.checklist.map(x=>`<label class="note"><input type="checkbox"> ${x}</label>`).join('')}<textarea readonly>${JSON.stringify(b,null,2)}</textarea></section>`}
function render(){root.innerHTML=hero()+({journey:journey,concepts:concepts,simulations:simulations,graph:graphView,proof:proof,case:caseStudio,reviewer:reviewer}[view])();drawGraph()}
fetch('data/oc_atlas.json').then(r=>r.json()).then(a=>{atlas=a;render()}).catch(e=>{root.innerHTML='<div class="shell"><h1>Atlas load failed</h1><p>'+e+'</p></div>'})
"""


def build_static_exhibit() -> None:
    DIST.mkdir(parents=True, exist_ok=True)
    data_dist = DIST / "data"
    if data_dist.exists():
        shutil.rmtree(data_dist)
    shutil.copytree(PUBLIC_DATA, data_dist)
    (DIST / "index.html").write_text(
        """<!doctype html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1.0"><title>Ontology of Continua Core 1.4</title><link rel="stylesheet" href="assets/styles.css"></head><body><div id="app" class="shell"></div><script src="assets/app.js"></script></body></html>""",
        encoding="utf-8",
    )
    assets = DIST / "assets"
    assets.mkdir(exist_ok=True)
    (assets / "styles.css").write_text(CSS, encoding="utf-8")
    (assets / "app.js").write_text(JS, encoding="utf-8")


def main() -> int:
    build_static_exhibit()
    print(json.dumps({"status": "PASS", "dist": str(DIST)}, indent=2))
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
